export function getSGKUnitsByGrade(grade: number): SGKUnit[] {
  return TEXTBOOK_UNITS_DATA.filter(u => u.grade === grade);
}

export function getSGKUnit(grade: number, unitNumber: number): SGKUnit | undefined {
  return TEXTBOOK_UNITS_DATA.find(u => u.grade === grade && u.unitNumber === unitNumber);
}
